def print_box(start_line, end_line, start_col, end_col):
    with open('/app/dataset/genealogy_trees.txt', 'r', encoding='utf-8') as f:
        lines = f.readlines()

    for i in range(start_line - 1, min(end_line, len(lines))):
        line = lines[i]
        # Pad with spaces if the line is shorter than end_col
        if len(line) < end_col:
            line = line.rstrip('\n') + ' ' * (end_col - len(line)) + '\n'
        print(f"{i+1:3d}: {line[start_col:end_col]}")

