with open('/app/dataset/genealogy_trees.txt', 'r', encoding='utf-8') as f:
    lines = [line.rstrip('\n') for line in f.readlines()]

def get_char(r, c):
    if 0 <= r < len(lines) and 0 <= c < len(lines[r]):
        return lines[r][c]
    return ' '

def get_exact_box(r_name, c_name, len_name):
    # Find left border: closest col to the left of c_name that has '|' or '│' on row r_name
    left_col = None
    for col in range(c_name - 1, -1, -1):
        if get_char(r_name, col) in ['|', '│']:
            left_col = col
            break
    if left_col is None:
        left_col = c_name - 1

    # Find right border: closest col to the right of c_name + len_name that has '|' or '│' on row r_name
    right_col = None
    for col in range(c_name + len_name, min(10000, len(lines[r_name]) + 20)):
        if get_char(r_name, col) in ['|', '│']:
            right_col = col
            break
    if right_col is None:
        right_col = c_name + len_name

    # Find top border
    top_row = None
    for r in range(r_name - 1, -1, -1):
        chars = [get_char(r, col) for col in range(left_col, right_col + 1)]
        if any(c in ['-', '~', '+', '_', '┌', '┐', '┬'] for c in chars):
            top_row = r
            break
    if top_row is None:
        top_row = r_name - 1

    # Find bottom border
    bottom_row = None
    for r in range(r_name + 1, len(lines)):
        chars = [get_char(r, col) for col in range(left_col, right_col + 1)]
        if any(c in ['-', '~', '+', '_', '└', '┘', '┴'] for c in chars):
            bottom_row = r
            break
    if bottom_row is None:
        bottom_row = r_name + 1

    return top_row, bottom_row, left_col, right_col

# Let's search for "Maksymilian" on any line
found = False
for r in range(len(lines)):
    idx = lines[r].find("Maksymilian")
    if idx != -1:
        print(f"Maksymilian on row {r} (0-indexed) at col {idx}")
        t_r, b_r, l_c, r_c = get_exact_box(r, idx, len("Maksymilian"))
        print(f"Refined box: r={t_r}..{b_r}, c={l_c}..{r_c}")
        for row in range(t_r, b_r + 1):
            chars = "".join(get_char(row, col) for col in range(l_c, r_c + 1))
            print(f"Row {row:3d}: {chars}")
        found = True
        break

